#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

namespace {

constexpr int TILE = 32;
__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    const int tile_row = blockIdx.y;
    const int tile_col = blockIdx.x;
    if (tile_col < tile_row) {
        return;
    }
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row_base = tile_row * TILE + ty * 4;
    const int col_base = tile_col * TILE + tx * 4;
    __shared__ float As[TILE][TILE + 1];
    __shared__ float Bs[TILE][TILE + 1];
    float acc[4][4] = {};
    const int first_k_tile = tile_row;
    const int last_k_tile = tile_col;
    for (int k_tile = first_k_tile; k_tile <= last_k_tile; ++k_tile) {
        const int k_base = k_tile * TILE;
        #pragma unroll
        for (int dy = 0; dy < 4; ++dy) {
            const int a_row = row_base + dy;
            const int a_col = k_base + tx * 4;
            const int b_row = k_base + ty * 4 + dy;
            const int b_col = col_base;
            if (a_row < N && a_col + 3 < N && a_col >= a_row &&
                ((a_row * N + a_col) & 3) == 0) {
                const float4 v = *reinterpret_cast<const float4*>(A + a_row * N + a_col);
                As[ty * 4 + dy][tx * 4 + 0] = v.x;
                As[ty * 4 + dy][tx * 4 + 1] = v.y;
                As[ty * 4 + dy][tx * 4 + 2] = v.z;
                As[ty * 4 + dy][tx * 4 + 3] = v.w;
            } else {
                #pragma unroll
                for (int dx = 0; dx < 4; ++dx) {
                    const int ar = a_row;
                    const int ac = a_col + dx;
                    As[ty * 4 + dy][tx * 4 + dx] =
                        (ar < N && ac < N && ac >= ar) ? A[ar * N + ac] : 0.0f;
                }
            }
            if (b_row < N && b_col + 3 < N && b_col >= b_row &&
                ((b_row * N + b_col) & 3) == 0) {
                const float4 v = *reinterpret_cast<const float4*>(B + b_row * N + b_col);
                Bs[ty * 4 + dy][tx * 4 + 0] = v.x;
                Bs[ty * 4 + dy][tx * 4 + 1] = v.y;
                Bs[ty * 4 + dy][tx * 4 + 2] = v.z;
                Bs[ty * 4 + dy][tx * 4 + 3] = v.w;
            } else {
                #pragma unroll
                for (int dx = 0; dx < 4; ++dx) {
                    const int br = b_row;
                    const int bc = b_col + dx;
                    Bs[ty * 4 + dy][tx * 4 + dx] =
                        (br < N && bc < N && bc >= br) ? B[br * N + bc] : 0.0f;
                }
            }
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a[4];
            float b[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                a[i] = As[ty * 4 + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b[j] = Bs[k][tx * 4 + j];
            }
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        const int row = row_base + i;
        const int col = col_base;
